package com.example.splitstory;
import java.io.*;import java.security.*;import java.security.cert.X509Certificate;
public class NativeExportHost {
static java.util.Map<String,File> media(File dir){java.util.Map<String,File> m=new java.util.TreeMap<>();File[] fs=dir.listFiles();if(fs!=null)for(File f:fs)m.put("assets/media/"+f.getName(),f);return m;}
public static void main(String[] args)throws Exception{KeyStore ks=KeyStore.getInstance("JKS");try(InputStream in=new FileInputStream("signing.jks")){ks.load(in,"event-vn-test".toCharArray());}PrivateKey key=(PrivateKey)ks.getKey("eventvn","event-vn-test".toCharArray());X509Certificate cert=(X509Certificate)ks.getCertificate("eventvn");File folder=new File("export-qa/work");folder.mkdirs();String pkg=ApkExportEngine.packageName(args[2],cert);ApkExportEngine.build(new File("assets/player-shell.apk"),new File(System.getProperty("editor","v0.1.64-Event-Game-Editor.apk")),new File(args[0]),new File(args[1]),folder,pkg,args[3],Integer.parseInt(args[4]),key,cert,args.length>5&&!args[5].isEmpty()?new File(args[5]):null,args.length>6?media(new File(args[6])):null,args.length>7&&!args[7].isEmpty()?new java.util.HashSet<>(java.util.Arrays.asList(args[7].split(","))):null,args.length>8?new java.util.HashSet<>(java.util.Arrays.asList(args[8].split(","))):null);System.out.println(pkg);}
}
